#!/usr/bin/env bash
# Full regression (docs/REGRESSION_TEST_REPORT.md). Needs: a local PostgreSQL (pg_ctlcluster 16 main start), Chromium (Playwright),
# APP_PIN in the environment (never written in the repository), AXE=/path/to/axe-core/axe.min.js for the a11y suite. A checkout that
# never built the data (no data2/clean.csv) skips "backup / restore" with a SKIP line; port 8766 must be free (a server left
# running there is answered instead of this checkout's app — stop it by PID first).
# Do not edit this file while it runs (bash reads it as it goes). Prints one line per suite and the failing lines; exit 1 on any failure.
set -u
cd "$(dirname "$0")/.."
: "${APP_PIN:?APP_PIN 환경 변수가 필요해요}"
PORT=8766; export BASE="http://localhost:$PORT/"
if (exec 3<>"/dev/tcp/127.0.0.1/$PORT") 2>/dev/null; then echo "FAIL | port $PORT is already in use — another server would be tested instead of this checkout; stop it first (ps -eo pid,cmd | grep http.server)"; exit 1; fi
python3 -m http.server $PORT --directory app >/dev/null 2>&1 & SRV=$!
trap 'kill $SRV 2>/dev/null' EXIT
sleep 1
fail=0
run() { local name="$1"; shift; local out; out=$("$@" 2>&1); local rc=$?
  local sum; sum=$(printf '%s\n' "$out" | grep -E '^[0-9]+/[0-9]+ passed|^# (pass|fail) [0-9]+|violations|passed|PASS:|FAIL:' | tail -3 | tr '\n' ' ')
  if [ $rc -eq 0 ]; then echo "OK   | $name | $sum"; else echo "FAIL | $name | $sum"; printf '%s\n' "$out" | grep -E '^FAIL|not ok|Error' | head -8; fail=1; fi; }
run "unit (tests/*.test.js)" bash -c "node --test tests/*.test.js"
run "server push pieces (allowlist, VAPID, quiet hours, rules)" bash -c "cd server && node --test test/push.test.mjs"
run "admin worker (cf/admin: fail-closed Access gate, headers, no sw.js)" bash -c "node --test cf/admin/test/*.test.mjs"
run "ops screen only on the admin host (browser)" node tests/security/admin_ops_browser.js
run "admin ops: regression list + browser check need APP_PIN" bash -c "node --test tests/security/*.test.js"
run "CSP vs config origins" node tools/check_csp.js
run "DB security policies" bash tests/db/run_security_tests.sh
run "secret scan" python3 tests/security/scan_secrets.py
run "security headers (app/_headers)" python3 tests/security/headers_test.py
run "comparison keys (xkeys)" python3 build2/xkeys.py
run "weekly value guard" python3 tests/weekly_guard_test.py
run "monitoring alerts (Telegram token never printed, checks; no network)" python3 tests/security/monitor_test.py
run "brand collectors (parsers on saved public pages)" python3 tests/brand_parsers_test.py
run "metrics worker (cf/metrics: 8 stages only, no IP stored, Access)" bash -c "node --test cf/metrics/test/*.test.mjs"
run "spec labels (no price/date/promo words, nothing we glued)" python3 tests/labels_test.py
run "data size guard (app/data.json under 20 MiB, guard runs in the build)" python3 tests/size_guard_test.py
run "branch addresses (own address, loose forms, on saved public pages)" python3 tests/branch_addr_test.py
# backup / restore needs the real current data as CSV files (data2/db/, git-ignored, made by build2/export_db.py from
# data2/clean.csv, which build2/weekly.py makes). A fresh checkout has neither: make what can be made from a clean.csv that is
# there; if there is none, say SKIP out loud (never OK, never a bare FAIL) and how to get it — the suite is not run, not passed.
if [ ! -f data2/db/offers.csv ] && [ -f data2/clean.csv ]; then python3 build2/export_db.py >/dev/null 2>&1; fi
if [ -f data2/db/offers.csv ]; then run "backup / restore" bash tests/db/backup_restore_test.sh
else echo "SKIP | backup / restore | no data2/db/offers.csv and no data2/clean.csv — run: python build2/weekly.py --skip-scrape && python build2/export_db.py"; fi
for t in accounts_r2 devices51 qa7 ux_qa concern xss jomi objective frame table_attr compare_cards v5_features demo_features data_sync o2_home o3_search pricenow audit40 taxonomy40 pricing40 ops40 audit_ui a11y touch_targets clickable price_focus first_screens metrics push alert_region addon_col cond_badge spec_notes new_chains; do
  run "e2e $t" node tests/e2e/$t.js
done
# A screen check added later (tests/e2e/ belongs to chat B; this file to A) runs too, without waiting for this list to name
# it: every other tests/e2e/*.js except helper modules (E2E_HELPERS — they only export code). The PR checks run no browser.
# Read from the repository root (the cd above), not "$0": run as `cd tests && bash run_regression.sh`, "$0" no longer resolves
# and every named check would run a second time.
E2E_LISTED=" $(sed -n 's/^for t in \(.*\); do$/\1/p' tests/run_regression.sh | head -1) "
case "$E2E_LISTED" in "  ") echo "FAIL | catch-all could not read the named e2e list from tests/run_regression.sh"; fail=1 ;; esac
E2E_HELPERS=" rows "
for f in tests/e2e/*.js; do
  t=$(basename "$f" .js)
  case "$E2E_LISTED$E2E_HELPERS" in *" $t "*) continue ;; esac
  run "e2e $t (not yet in the list above)" node "tests/e2e/$t.js"
done
exit $fail
